<style>

.dashboard_top {
  position: relative;
  container-type: inline-size;
  container-name: dash;
  width: 100%;
  background-color: #F0F;
}

.dashboard_full {
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  right: 0;
}

.dashboard_needle {
  fill: #F64;
  stroke: #832;
  stroke-width: 0.01;
  filter: drop-shadow(0px 0px 0.1px #F648);
}

.dashboard_occlusion {
  filter: drop-shadow(0px 0px 0.3px #0008) drop-shadow(0px 0px 0.1px #000);
}

.dashboard_primary {
  fill: #AF8;
  text-anchor: middle;
  dominant-baseline: central;
  filter: drop-shadow(0px 0px 0.05px #AF86);
}

.dashboard_secondary {
  fill: #FA8;
  text-anchor: middle;
  dominant-baseline: central;
  filter: drop-shadow(0px 0px 0.05px #FA86);
}

.dashboard_segment {
  fill: #0002;
}

.dashboard_desg7 {
  font-family: "DSEG7 Classic Mini", monospace;
  font-style: italic;
  text-anchor: middle;
}

.dashboard_desg14 {
  font-family: "DSEG14 Classic Mini", monospace;
  font-style: italic;
  text-anchor: middle;
}

.dashboard {
  position: relative;
  container-type: inline-size;
  container-name: dash;
  width: 100%;
  aspect-ratio: 13 / 6;
  background-color: #300;
}

.noobs {
  position: absolute;
  left: 10%;
  width: 10%;
  top: 10%;
  height: 10%;
  background-color: #030;
}

.positioned {
  position: absolute;
  transform: translate(-50%, -50%);
}

body {
  color: #E0E0E0;
  background-color: #0C0C0C;
  font-family: Roboto, "Helvetica Neue", sans-serif;
}

span.seg7 {
  font-family: "DSEG7 Classic Mini", monospace;
}

span.seg14 {
  font-family: "DSEG14 Classic Mini", monospace;
}

span.seg7, span.seg14 {
  font-style: italic;
  font-size: 4cqi;
  position: relative;
}

span.seg7 span:nth-of-type(1), span.seg14 span:nth-of-type(1) {
  z-index: 100;
  position: absolute;
  top: 0;
  white-space: nowrap;
}

span.seg7 span:nth-of-type(2), span.seg14 span:nth-of-type(2) {
  z-index: 50;
  position: absolute;
  top: 0;
  white-space: nowrap;
  color: #101010;
}

.indicator-off {
  color: #101010;
}

.indicator-red {
  color: #FF0000;
}

.indicator-amber {
  color: #FFAA00;
}

.indicator-green {
  color: #00FF60;
}

.indicator-blue {
  color: #0044FF;
}

.indicator-gray {
  color: #CCCCCC;
}

.gauge {
  aspect-ratio: 1;
  container-type: inline-size;
  display: grid;
  grid-template: repeat(3, 1fr) / repeat(3, 1fr);
  inline-size: 100%;
}

.gauge-gauge {
  background: conic-gradient(from 235deg, #8CF, #6BF, #46E, #24C 220deg, #0000 220deg);
  border-radius: 50%;
  grid-area: 1 / 1 / 4 / 4;
  mask: radial-gradient(circle at 50% 50%, #0000 0%, #fff 100%);
  mask-composite: subtract;
}

.off {
  color: #FFF !important;
}

.red {
  color: #F00;
}


</style>